#!/usr/bin/env python3
"""F6 / PR-HCSI-S084: extended rank-4 RANDOM control family for the button r4 VALIDATION re-test.

Builds a NEW basis file (never modifies configs/heretic_csi/hcsi_ranksweep_button.pt) containing:
  * cand_pls4  -- byte-identical copy of the frozen candidate (needed in-file as the norm-match key that
                  score_behavior's --rescue-norm-match-key resolves against; sha16 asserted equal);
  * ctrl_random_r4_{46..46+N-1} -- N NEW random orthonormal rank-4 bases, generated by the SAME code path
                  as scripts/dcs_csi_axis.py (M = randn(R, hidden, float64); Q = qr(M.T)[0].T), from a NEW,
                  disjoint generator seed (20261014; dcs_csi_axis used 20260915), indices continuing after
                  the existing 0..45 so arm/run-dir tags never collide.
Norm matching is done at scoring time exactly as for the original 46 (each control is rescaled to the
candidate's written-delta norm by score_behavior via --rescue-norm-match-key cand_pls4).
"""
from __future__ import annotations
import argparse, json, os, sys
import torch

sys.path.insert(0, os.path.dirname(__file__))
from learned_projector import save_basis, sha16  # byte-exact frozen format (S-008)

SRC = "configs/heretic_csi/hcsi_ranksweep_button.pt"


def build(n_new: int, seed: int, start: int, R: int = 4):
    src = torch.load(SRC, map_location="cpu", weights_only=False)
    cand = src["bases"]["cand_pls4"]
    hidden = cand.shape[1]
    existing = {k: v for k, v in src["bases"].items() if k.startswith(f"ctrl_random_r{R}_")}
    assert len(existing) == 46 and start == 46, (len(existing), start)
    g = torch.Generator().manual_seed(seed)
    bases = {"cand_pls4": cand.clone()}
    for i in range(start, start + n_new):
        M = torch.randn(R, hidden, generator=g, dtype=torch.float64)
        bases[f"ctrl_random_r{R}_{i}"] = torch.linalg.qr(M.T)[0].T.contiguous()
    meta = {"schema": "hcsi_p2a_r4ext/1", "prereg": "PR-HCSI-S084", "source_pt": SRC,
            "source_meta_seed": src["meta"]["seed"], "new_generator_seed": seed,
            "new_keys": f"ctrl_random_r{R}_{start}..{start + n_new - 1}", "rank": R, "hidden": hidden,
            "generation": "M=randn(R,hidden,float64,generator); Q=qr(M.T)[0].T (dcs_csi_axis.py code path)",
            "cand_pls4_sha16_source": src["meta"]["bases"]["cand_pls4"]["sha16"]}
    return bases, meta, existing


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--n-new", type=int, default=144)
    ap.add_argument("--seed", type=int, default=20261014)
    ap.add_argument("--out", default="configs/heretic_csi/hcsi_ranksweep_button_r4ext.pt")
    a = ap.parse_args()
    bases, meta, existing = build(a.n_new, a.seed, 46)
    save_basis(bases, meta, a.out)
    saved = torch.load(a.out, map_location="cpu", weights_only=False)["bases"]  # re-read the bytes on disk
    assert sha16(saved["cand_pls4"]) == meta["cand_pls4_sha16_source"], "candidate copy is not byte-identical"
    print(json.dumps({"out": a.out, "n_keys": len(saved), "cand_sha16": sha16(saved["cand_pls4"])}))


if __name__ == "__main__":
    main()
